    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
n = rng.randint(3, 12)
c = rng.randint(2, 7)
A = c**2
B = c**4
return {
    'n': n,
    'c': c,
    'A': A,
    'B': B
}

    def verifier(assign):
n = assign['n']
c = assign['c']
A = assign['A']
B = assign['B']

# Validate parameters
if not (isinstance(n, int) and isinstance(c, int) and n >= 3 and c >= 2):
    return False, None # Parameter constraints for difficulty
if A != c**2 or B != c**4:
    return False, None # Structural constraint of the problem

# Direct computation of the formula for verification
# This is slow but robust, using Python's arbitrary-precision integers.
def f(m):
    return m**4 + A * m**2 + B

num_prod = 1
for k in range(1, n + 1):
    num_prod *= f(2 * c * k)

den_prod = 1
for k in range(1, n + 1):
    den_prod *= f(c * (2 * k - 1))

if den_prod == 0:
    return False, None # Avoid division by zero

# The result must be an integer.
if num_prod % den_prod != 0:
    return False, None

result = num_prod // den_prod

# Compare with the theoretical answer from the derived formula.
expected_answer = 4 * n**2 + 2 * n + 1

if result != expected_answer:
    return False, None # Mismatch between brute-force and formula

return True, expected_answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
